with with_latest as (select s.*, top1.order_item_unit_price from products s left join lateral (select c.unit_price as order_item_unit_price from order_items c where c.product_id = s.id order by c.unit_price desc, c.id desc limit 1) top1 on true), enriched as (select e.*, s.country from with_latest e left join suppliers s on e.supplier_id <=> s.id), latest as (select id, price, tags, supplier_id, country from (select *, row_number() over (partition by brand order by launch_date nulls last, id) as rank_in_group from enriched) x where rank_in_group = 1), with_dims as (select a.*, s.supplier_name from latest a left join suppliers s on a.supplier_id = s.id where s.city = 'Berlin'), with_dims_products as (select s.*, p2.rating, p2.country as supplier_country, p2.city from with_dims s left join suppliers p2 on s.supplier_id = p2.id), eligible as (select s.* from with_dims_products s where not exists (select 1 from order_items ch where ch.product_id = s.id and ch.quantity between 5 and 6)) select s.id, s.price, s.supplier_id, s.country, s.supplier_name, s.rating, s.supplier_country, s.city, (select sum(x.stock_qty) from products x where x.supplier_id = s.supplier_id) as sum_product_stock_qty from eligible s;
